 summary=dict(rupees=value(0x3a,2),health_raw=value(0x36,2),health_capacity_raw=value(0x34,2),deku_nuts=value(0xa9,1),deku_nut_item=hex(value(0x79,1)),equipment_raw=hex(equip),sword_level=equip&15,shield_level=(equip>>4)&15,wallet_level=(upgrade>>12)&3,wallet_capacity=[99,200,500,500][(upgrade>>12)&3])
 data=bytearray(ram[BASE:BASE+0x100c]);stored=int.from_bytes(data[0x100a:0x100c],'big');data[0x100a:0x100c]=b'\0\0'
