  if zipfile.is_zipfile(src):
   with zipfile.ZipFile(src) as z:
    members=[i for i in z.infolist() if i.filename.lower().endswith('.png') and not i.is_dir()]
    if not members:raise ValueError('ZIP sin PNG')
    for info in members:
     if info.file_size>32*1024*1024:raise ValueError('PNG supera limite de 32 MiB')
